// GENERATED by scripts/sync-shared.mjs from src/lib. Do not edit by hand.
// Curation: a small, explainable ranking. No engagement signals, no hidden
// model: relevance, significance, novelty, timeliness, diversity, discovery,
// personal importance and narrative continuity. Every entry carries the
// reasons it was chosen.
import type { AppState, Interest, Item, Series } from "./types.ts";
import { matchingInterests, norm, priorityLabel } from "./ledger.ts";

export interface Signal {
  label: string;
  value: string;
}

export interface FeedEntry {
  key: string; // item id or `pitch:${seriesId}`
  kind: "item" | "pitch";
  item?: Item;
  series?: Series;
  score: number;
  relevance: number;
  discovery: boolean;
  reason: string;
  signals: Signal[];
}

const DAY = 86_400_000;

export function isHidden(state: AppState, topics: string[]): boolean {
  const blocked = new Set(state.prefs.excludedTopics.map(norm));
  for (const t of topics) if (blocked.has(norm(t))) return true;
  // Muting or excluding a subject hides anything that touches it, even if the story also fits something else.
  return matchingInterests(state.interests, topics).some((h) => h.status === "excluded" || h.status === "muted");
}

export function seriesProgress(state: AppState, series: Series, items: Item[]) {
  const chapters = items
    .filter((i) => i.seriesId === series.id && i.status !== "archived")
    .sort((a, b) => (a.chapter ?? 0) - (b.chapter ?? 0));
  const read = chapters.filter((c) => state.progress[c.id]?.status === "read").length;
  const next = chapters.find((c) => state.progress[c.id]?.status !== "read");
  const lastOpened = chapters
    .map((c) => state.progress[c.id]?.lastOpened)
    .filter(Boolean)
    .sort()
    .pop();
  return { chapters, read, next, complete: chapters.length > 0 && read === chapters.length && chapters.length >= series.totalChapters, lastOpened };
}

/** Series the reader has started and not finished, oldest first. */
export function activeSeries(state: AppState, series: Series[], items: Item[]): Series[] {
  return series
    .filter((s) => state.seriesStarted[s.id])
    .filter((s) => !seriesProgress(state, s, items).complete)
    .sort((a, b) => state.seriesStarted[a.id].localeCompare(state.seriesStarted[b.id]));
}

function relevanceFor(state: AppState, topics: string[]): { rel: number; via?: Interest; followed?: string } {
  const hits = matchingInterests(state.interests, topics).filter((h) => h.status === "active");
  let rel = 0.12;
  let via: Interest | undefined;
  for (const h of hits) {
    const v = h.weight * (0.55 + 0.45 * h.confidence);
    if (v > rel || !via) { rel = Math.max(rel, v); via = h; }
  }
  const followed = topics.find((t) => state.followed.some((f) => norm(f) === norm(t)));
  if (followed) rel = Math.min(1, rel + 0.15);
  return { rel, via, followed };
}

function timeScore(item: Item, eb: number, now: number): number {
  if (item.timeliness === "evergreen") return 0.55 + 0.45 * eb;
  // Sample items are dated by when they were "published", so the demo stays fresh.
  const days = Math.max(0, (now - Date.parse(item.sample ? item.publishedAt : item.eventDate ?? item.publishedAt)) / DAY);
  const fresh = Math.pow(0.5, days / 6);
  return (0.35 + 0.65 * fresh) * (1 - 0.5 * eb);
}

export function rank(state: AppState, items: Item[], series: Series[], now = Date.now()): FeedEntry[] {
  const entries: FeedEntry[] = [];
  const seriesMap = new Map(series.map((s) => [s.id, s]));
  const active = activeSeries(state, series, items);
  const eligibleSeries = new Set(active.slice(0, state.prefs.activeSeries).map((s) => s.id));
  const recentTopics = Object.values(state.progress)
    .filter((p) => p.status === "read")
    .sort((a, b) => b.lastOpened.localeCompare(a.lastOpened))
    .slice(0, 6)
    .flatMap((p) => items.find((i) => i.id === p.itemId)?.topics ?? [])
    .map(norm);

  // Which chapter of each series is next
  const nextChapter = new Map<string, Item>();
  for (const s of series) {
    const pr = seriesProgress(state, s, items);
    if (pr.next) nextChapter.set(s.id, pr.next);
  }

  for (const item of items) {
    if (item.status === "archived") continue;
    if (state.dismissed.includes(item.id)) continue;
    const prog = state.progress[item.id];
    const isRead = prog?.status === "read";

    if (item.format === "series_chapter") {
      if (!item.seriesId || !eligibleSeries.has(item.seriesId)) continue;
      if (nextChapter.get(item.seriesId)?.id !== item.id) continue; // never skip ahead, never repeat
    } else if (isRead) continue;

    const s = item.seriesId ? seriesMap.get(item.seriesId) : undefined;
    const topics = [...item.topics, ...(s?.topics ?? [])];
    if (isHidden(state, topics)) continue;

    const { rel, via, followed } = relevanceFor(state, topics);
    const novelty = recentTopics.some((t) => item.topics.map(norm).includes(t)) ? 0.8 : 1;
    const time = timeScore(item, state.prefs.evergreenBalance, now);
    let score = 0.38 * rel + 0.22 * item.significance + 0.12 * novelty + 0.18 * time + 0.1 * (state.prefs.formatMix[item.format as keyof AppState["prefs"]["formatMix"]] ?? 0.6);
    const signals: Signal[] = [
      { label: "Relevance", value: via ? `${priorityLabel(via.weight)} · ${via.name}` : "Outside your usual lanes" },
      { label: "Significance", value: item.significance >= 0.75 ? "High" : item.significance >= 0.5 ? "Solid" : "Gentle" },
      { label: "Timing", value: item.timeliness === "evergreen" ? "Evergreen" : "Current" },
    ];
    let reason = "";
    let discovery = !via || rel < 0.3;

    if (item.format === "series_chapter" && s) {
      score += 0.35; // narrative continuity
      discovery = false;
      const pr = seriesProgress(state, s, items);
      reason = pr.read === 0
        ? `Chapter 1 of “${s.title}”. You said yes to this one.`
        : `Next up in “${s.title}”. You've read ${pr.read} of ${s.totalChapters}, and I never skip ahead.`;
      signals.push({ label: "Series", value: `Chapter ${item.chapter} of ${s.totalChapters}` });
    } else if (item.format === "circle") {
      const person = state.people.find((p) => norm(p.name) === norm(item.person ?? ""));
      const close = person?.closeness ?? 2;
      const freq = { rare: 0.7, occasional: 1, often: 1.3 }[state.prefs.circleFrequency];
      score += (close === 1 ? 0.42 : close === 2 ? 0.28 : 0.14) * freq;
      discovery = false;
      reason = `News about ${item.person ?? "someone in your circle"}. I surface these whatever the topic, because people matter more than categories. 🍓`;
      signals.push({ label: "Personal importance", value: close === 1 ? "Close" : close === 2 ? "Friend" : "Acquaintance" });
    } else if (discovery) {
      reason = `A little outside your usual lanes. I like to slip one in now and then, so the feed doesn't just echo you back. 🍎`;
    } else if (followed) {
      reason = `You follow “${followed}”.`;
    } else if (via) {
      const kind = item.timeliness === "evergreen" ? "A story that keeps" : "A development worth knowing";
      reason = `${kind}, and it fits your ${priorityLabel(via.weight).toLowerCase()}-priority interest in ${via.name}${via.origin === "inferred" ? " (which I inferred, so tell me if I'm wrong)" : ""}.`;
    }
    if (item.reason) reason += ` ${item.reason}`;

    entries.push({ key: item.id, kind: "item", item, series: s, score, relevance: rel, discovery, reason: reason.trim(), signals });
  }

  // Series pitches the reader hasn't answered. One at a time, only if there's room.
  if (active.length < state.prefs.activeSeries) {
    const pitch = series
      .filter((s) => s.status === "suggested" || (!state.seriesStarted[s.id] && s.researchStatus !== "pitched"))
      .filter((s) => !state.seriesStarted[s.id])
      .filter((s) => !state.feedback.some((f) => f.seriesId === s.id && f.type === "series-no"))
      .filter((s) => !isHidden(state, s.topics))
      .map((s) => ({ s, ...relevanceFor(state, s.topics) }))
      .sort((a, b) => b.rel - a.rel)[0];
    if (pitch) {
      entries.push({
        key: `pitch:${pitch.s.id}`, kind: "pitch", series: pitch.s,
        score: 0.55 + 0.3 * pitch.rel,
        relevance: pitch.rel, discovery: false,
        reason: pitch.s.reason ?? "I think you'd like this one.",
        signals: [{ label: "Relevance", value: pitch.via ? pitch.via.name : "A new direction" }],
      });
    }
  }

  return sequence(entries, state);
}

/** Order by score, then repair the order for diversity, format variety and a steady drip of discovery. */
function sequence(entries: FeedEntry[], state: AppState): FeedEntry[] {
  const pool = [...entries].sort((a, b) => b.score - a.score);
  const out: FeedEntry[] = [];
  const topicOf = (e: FeedEntry) => norm(e.item?.topics[0] ?? e.series?.topics[0] ?? "");
  const diversity = 1 - state.prefs.focus * 0.7;
  const everyN = Math.max(3, Math.round(1 / Math.max(0.08, state.prefs.discovery)));

  while (pool.length) {
    const pos = out.length;
    let pickIdx = -1;
    if (pos > 0 && pos % everyN === everyN - 1) {
      pickIdx = pool.findIndex((e) => e.discovery && e.kind === "item");
    }
    if (pickIdx < 0) {
      let best = -Infinity;
      pool.forEach((e, idx) => {
        const recent = out.slice(-3);
        const sameTopic = recent.filter((r) => topicOf(r) === topicOf(e)).length;
        const sameFormat = recent.slice(-2).filter((r) => r.item?.format && r.item.format === e.item?.format).length;
        const adj = e.score - sameTopic * 0.16 * diversity - sameFormat * 0.05;
        if (adj > best) { best = adj; pickIdx = idx; }
      });
    }
    out.push(pool.splice(pickIdx, 1)[0]);
  }
  return out;
}

/**
 * Keep the feed stable. Whatever the reader has already been shown keeps its
 * place; newly eligible stories settle in beneath the next few unread items,
 * never above the reader's position.
 */
export function mergeSnapshot(
  snapshot: string[],
  ranked: FeedEntry[],
  anchorKey: string | undefined,
  keepKeys: Set<string> = new Set(),
  keepNext = 5,
): { order: string[]; fresh: number } {
  const eligible = new Set(ranked.map((r) => r.key));
  const kept = snapshot.filter((k) => eligible.has(k) || keepKeys.has(k));
  const known = new Set(kept);
  const newcomers = ranked.filter((r) => !known.has(r.key));
  if (kept.length === 0) return { order: ranked.map((r) => r.key), fresh: 0 };
  let anchorIdx = anchorKey ? kept.indexOf(anchorKey) : -1;
  if (anchorIdx < 0) anchorIdx = -1;
  const head = kept.slice(0, anchorIdx + 1);
  const tail = kept.slice(anchorIdx + 1);
  const fixed = tail.slice(0, keepNext);
  const flex = tail.slice(keepNext);
  const pos = new Map(ranked.map((r, i) => [r.key, i]));
  const flexAll = [...flex, ...newcomers.map((n) => n.key)].sort((a, b) => (pos.get(a) ?? 1e9) - (pos.get(b) ?? 1e9));
  return { order: [...head, ...fixed, ...flexAll], fresh: newcomers.length };
}
